import{_ as s,a0 as r,w as u,s as a,I as l,x as n,a1 as t,A as o,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"SELinux 入门 | LCTT x X-CMD","titleTemplate":false,"description":"SELinux 入门 | LCTT (201605) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"SELinux 入门 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"SELinux 入门 | LCTT (201605) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201605/20160204 An Introduction to SELinux","title":"SELinux 入门","tag":"201605","desc":""},"relativePath":"201605/20160204 An Introduction to SELinux.md","filePath":"[post].md"}'),d={name:"201605/20160204 An Introduction to SELinux.md"};function x(L,i,S,m,E,f){const e=r("Link");return u(),a("div",null,[i[23]||(i[23]=l("h1",{id:"selinux-入门",tabindex:"-1"},[n("SELinux 入门 "),l("a",{class:"header-anchor",href:"#selinux-入门","aria-label":"Permalink to “SELinux 入门”"},"​")],-1)),l("p",null,[i[2]||(i[2]=n("回到 Kernel 2.6 时代，那时候引入了一个新的安全系统，用以提供访问控制安全策略的机制。这个系统就是 ",-1)),t(e,{href:"http://selinuxproject.org/page/Main_Page"},{default:o(()=>[...i[0]||(i[0]=[n("Security Enhanced Linux (SELinux)",-1)])]),_:1}),i[3]||(i[3]=n("，它是由",-1)),t(e,{href:"https://www.nsa.gov/research/selinux/"},{default:o(()=>[...i[1]||(i[1]=[n("美国国家安全局（NSA）",-1)])]),_:1}),i[4]||(i[4]=n("贡献的，它为 Linux 内核子系统引入了一个健壮的强制控制访问（Mandatory Access Control）架构。",-1))]),i[24]||(i[24]=p(`<p>如果你在之前的 Linux 生涯中都禁用或忽略了 SELinux，这篇文章就是专门为你写的：这是一篇对存在于你的 Linux 桌面或服务器之下的 SELinux 系统的介绍，它能够限制权限，甚至消除程序或守护进程的脆弱性而造成破坏的可能性。</p><p>在我开始之前，你应该已经了解的是 SELinux 主要是红帽 Red Hat Linux 以及它的衍生发行版上的一个工具。类似地， Ubuntu 和 SUSE（以及它们的衍生发行版）使用的是 AppArmor。SELinux 和 AppArmor 有显著的不同。你可以在 SUSE，openSUSE，Ubuntu 等等发行版上安装 SELinux，但这是项难以置信的挑战，除非你十分精通 Linux。</p><p>说了这么多，让我来向你介绍 SELinux。</p><h3 id="dac-vs-mac" tabindex="-1">DAC vs. MAC <a class="header-anchor" href="#dac-vs-mac" aria-label="Permalink to “DAC vs. MAC”">​</a></h3><p>Linux 上传统的访问控制标准是自主访问控制（Discretionary Access Control，DAC）。在这种形式下，一个软件或守护进程以 User ID（UID）或 Set owner User ID（SUID）的身份运行，并且拥有该用户的目标（文件、套接字、以及其它进程）权限。这使得恶意代码很容易运行在特定权限之下，从而取得访问关键的子系统的权限。</p><p>另一方面，强制访问控制（Mandatory Access Control，MAC）基于保密性和完整性强制信息的隔离以限制破坏。该限制单元独立于传统的 Linux 安全机制运作，并且没有超级用户的概念。</p><h3 id="selinux-如何工作" tabindex="-1">SELinux 如何工作 <a class="header-anchor" href="#selinux-如何工作" aria-label="Permalink to “SELinux 如何工作”">​</a></h3><p>考虑一下 SELinux 的相关概念:</p><ul><li>主体（Subjects）</li><li>目标（Objects）</li><li>策略（Policy）</li><li>模式（Mode）</li></ul><p>当一个主体（Subject，如一个程序）尝试访问一个目标（Object，如一个文件），SELinux 安全服务器（SELinux Security Server，在内核中）从策略数据库（Policy Database）中运行一个检查。基于当前的模式（mode），如果 SELinux 安全服务器授予权限，该主体就能够访问该目标。如果 SELinux 安全服务器拒绝了权限，就会在 /var/log/messages 中记录一条拒绝信息。</p><p>听起来相对比较简单是不是？实际上过程要更加复杂，但为了简化介绍，只列出了重要的步骤。</p><h3 id="模式" tabindex="-1">模式 <a class="header-anchor" href="#模式" aria-label="Permalink to “模式”">​</a></h3><p>SELinux 有三个模式（可以由用户设置）。这些模式将规定 SELinux 在主体请求时如何应对。这些模式是：</p><ul><li>Enforcing （强制）— SELinux 策略强制执行，基于 SELinux 策略规则授予或拒绝主体对目标的访问</li><li>Permissive （宽容）— SELinux 策略不强制执行，不实际拒绝访问，但会有拒绝信息写入日志</li><li>Disabled （禁用）— 完全禁用 SELinux</li></ul><p><img src="https://www.linux.com/images/stories/66866/jack2-selinux_a.png" alt=""></p><p><em>图 1：getenforce 命令显示 SELinux 的状态是 Enforcing 启用状态。</em></p><p>默认情况下，大部分系统的 SELinux 设置为 Enforcing。你要如何知道你的系统当前是什么模式？你可以使用一条简单的命令来查看，这条命令就是 <code>getenforce</code>。这个命令用起来难以置信的简单（因为它仅仅用来报告 SELinux 的模式）。要使用这个工具，打开一个终端窗口并执行 <code>getenforce</code> 命令。命令会返回 Enforcing、Permissive，或者 Disabled（见上方图 1）。</p><p>设置 SELinux 的模式实际上很简单——取决于你想设置什么模式。记住：<strong>永远不推荐关闭 SELinux</strong>。为什么？当你这么做了，就会出现这种可能性：你磁盘上的文件可能会被打上错误的权限标签，需要你重新标记权限才能修复。而且你无法修改一个以 Disabled 模式启动的系统的模式。你的最佳模式是 Enforcing 或者 Permissive。</p><p>你可以从命令行或 <code>/etc/selinux/config</code> 文件更改 SELinux 的模式。要从命令行设置模式，你可以使用 <code>setenforce</code> 工具。要设置 Enforcing 模式，按下面这么做：</p><ol><li>打开一个终端窗口</li><li>执行 <code>su</code> 然后输入你的管理员密码</li><li>执行 <code>setenforce 1</code></li><li>执行 <code>getenforce</code> 确定模式已经正确设置（图 2）</li></ol><p><img src="https://www.linux.com/images/stories/66866/jack-selinux_b.png" alt=""></p><p><em>图 2：设置 SELinux 模式为 Enforcing。</em></p><p>要设置模式为 Permissive，这么做：</p><ol><li>打开一个终端窗口</li><li>执行 <code>su</code> 然后输入你的管理员密码</li><li>执行 <code>setenforce 0</code></li><li>执行 <code>getenforce</code> 确定模式已经正确设置（图 3）</li></ol><p><img src="https://www.linux.com/images/stories/66866/jack-selinux_c.png" alt=""></p><p><em>图 3：设置 SELinux 模式为 Permissive。</em></p><p>注：通过命令行设置模式会覆盖 SELinux 配置文件中的设置。</p><p>如果你更愿意在 SELinux 命令文件中设置模式，用你喜欢的编辑器打开那个文件找到这一行：</p><pre><code>SELINUX=permissive
</code></pre><p>你可以按你的偏好设置模式，然后保存文件。</p><p>还有第三种方法修改 SELinux 的模式（通过 bootloader），但我不推荐新用户这么做。</p><h3 id="策略类型" tabindex="-1">策略类型 <a class="header-anchor" href="#策略类型" aria-label="Permalink to “策略类型”">​</a></h3><p>SELinux 策略有两种：</p><ul><li>Targeted — 只有目标网络进程（dhcpd，httpd，named，nscd，ntpd，portmap，snmpd，squid，以及 syslogd）受保护</li><li>Strict — 对所有进程完全的 SELinux 保护</li></ul><p>你可以在 <code>/etc/selinux/config</code> 文件中修改策略类型。用你喜欢的编辑器打开这个文件找到这一行：</p><pre><code>SELINUXTYPE=targeted
</code></pre><p>修改这个选项为 targeted 或 strict 以满足你的需求。</p><h3 id="检查完整的-selinux-状态" tabindex="-1">检查完整的 SELinux 状态 <a class="header-anchor" href="#检查完整的-selinux-状态" aria-label="Permalink to “检查完整的 SELinux 状态”">​</a></h3><p>有个方便的 SELinux 工具，你可能想要用它来获取你启用了 SELinux 的系统的详细状态报告。这个命令在终端像这样运行：</p><pre><code>sestatus -v
</code></pre><p>你可以看到像图 4 那样的输出。</p><p><img src="https://www.linux.com/images/stories/66866/jack-selinux_d.png" alt=""></p><p><em>图 4：sestatus -v 命令的输出。</em></p><h3 id="仅是皮毛" tabindex="-1">仅是皮毛 <a class="header-anchor" href="#仅是皮毛" aria-label="Permalink to “仅是皮毛”">​</a></h3><p>和你预想的一样，我只介绍了 SELinux 的一点皮毛。SELinux 的确是个复杂的系统，想要更扎实地理解它是如何工作的，以及了解如何让它更好地为你的桌面或服务器工作需要更加地深入学习。我的内容还没有覆盖到疑难解答和创建自定义 SELinux 策略。</p>`,45)),l("p",null,[i[6]||(i[6]=n("SELinux 是所有 Linux 管理员都应该知道的强大工具。现在已经向你介绍了 SELinux，我强烈推荐你回到 Linux.com（当有更多关于此话题的文章发表的时候）或看看 ",-1)),t(e,{href:"https://www.nsa.gov/research/selinux/docs.shtml"},{default:o(()=>[...i[5]||(i[5]=[n("NSA SELinux 文档",-1)])]),_:1}),i[7]||(i[7]=n(" 获得更加深入的指南。",-1))]),l("p",null,[i[9]||(i[9]=n("LCTT - 相关阅读：",-1)),t(e,{href:"http://vbird.dic.ksu.edu.tw/linux_basic/0440processcontrol_5.php"},{default:o(()=>[...i[8]||(i[8]=[n("鸟哥的 Linux 私房菜——程序管理与 SELinux 初探",-1)])]),_:1})]),i[25]||(i[25]=l("hr",null,null,-1)),l("p",null,[i[11]||(i[11]=n("via: ",-1)),t(e,{href:"https://www.linux.com/learn/docs/ldp/883671-an-introduction-to-selinux"},{default:o(()=>[...i[10]||(i[10]=[n("https://www.linux.com/learn/docs/ldp/883671-an-introduction-to-selinux",-1)])]),_:1})]),l("p",null,[i[15]||(i[15]=n("作者：",-1)),t(e,{href:"https://www.linux.com/community/forums/person/93"},{default:o(()=>[...i[12]||(i[12]=[n("Jack Wallen",-1)])]),_:1}),i[16]||(i[16]=n(" 译者：",-1)),t(e,{href:"https://github.com/alim0x"},{default:o(()=>[...i[13]||(i[13]=[n("alim0x",-1)])]),_:1}),i[17]||(i[17]=n(" 校对：",-1)),t(e,{href:"https://github.com/wxy"},{default:o(()=>[...i[14]||(i[14]=[n("wxy",-1)])]),_:1})]),l("p",null,[i[20]||(i[20]=n("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...i[18]||(i[18]=[n("LCTT",-1)])]),_:1}),i[21]||(i[21]=n(" 原创编译，",-1)),t(e,{href:"https://linux.cn/"},{default:o(()=>[...i[19]||(i[19]=[n("Linux中国",-1)])]),_:1}),i[22]||(i[22]=n(" 荣誉推出",-1))])])}const b=s(d,[["render",x]]);export{w as __pageData,b as default};
